function drawerLootFor(id,tier='standard'){
 const seed=[id,tier,floorFive?.layoutSeed||0,floorOne?.layoutSeed||0,floorTwo?.seed||0,HOTEL_VISIT_SEED].join('|');let hash=2166136261;for(let index=0;index<seed.length;index++){hash^=seed.charCodeAt(index);hash=Math.imul(hash,16777619)}const roll=(hash>>>0)%100,amount=1+((hash>>>8)&1);
 if(tier==='premium'){if(roll<12)return{id:'gold',amount:amount+1};if(roll<31)return{id:'bandage',amount:2};if(roll<47)return{id:'energy-drink',amount:1};if(roll<63)return{id:'glowstick',amount:2};if(roll<76)return{id:'flashlight-battery',amount:1};if(roll<87)return{id:'lockpick',amount:1};if(roll<96)return{id:'wind-up-decoy',amount:1};return{id:'medkit',amount:1}}
 if(roll<34)return{id:'gold',amount};if(roll<52)return{id:'bandage',amount:1};if(roll<66)return{id:'energy-drink',amount:1};if(roll<80)return{id:'glowstick',amount:1};if(roll<89)return{id:'flashlight-battery',amount:1};if(roll<96)return{id:'lockpick',amount:1};return{id:'wind-up-decoy',amount:1}
}
