function playRansackChime(failed=false){try{funAudio||=new AudioContext();const context=funAudio,gain=context.createGain();gain.gain.setValueAtTime(.0001,context.currentTime);gain.gain.exponentialRampToValueAtTime(failed?.24:.15,context.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.0001,context.currentTime+.55);gain.connect(context.destination);for(const [frequency,delay] of (failed?[[110,0],[82,.14],[55,.28]]:[[740,0],[988,.12],[1240,.24]])){const oscillator=context.createOscillator();oscillator.type=failed?'sawtooth':'sine';oscillator.frequency.value=frequency;oscillator.connect(gain);oscillator.start(context.currentTime+delay);oscillator.stop(context.currentTime+delay+.25)}}catch{}}
