function setRansackHud(phase,copy,time=0,progress=0){const hud=document.querySelector('#ransack-hud');if(!hud)return;hud.classList.add('active');hud.classList.toggle('failed',phase==='COLLECT');hud.classList.toggle('passed',phase==='PASSED');hud.setAttribute('aria-hidden','false');document.querySelector('#ransack-sign').textContent=phase==='COLLECT'?'FAILED':phase==='PASSED'?'GOOD':'STOP';document.querySelector('#ransack-time').textContent=phase==='COLLECT'?`${ransack.collected} / ${ransack.total}`:phase==='PASSED'?'CLEAR':Math.max(0,time).toFixed(1);document.querySelector('#ransack-progress').style.transform=`scaleX(${THREE.MathUtils.clamp(progress,0,1)})`;document.querySelector('#ransack-instruction').textContent=copy;document.body.dataset.ransackPhase=ransack.phase}
