function placeRansackEntity(){const forward=new THREE.Vector3();camera.getWorldDirection(forward);forward.y=0;if(forward.lengthSq()<.01)forward.set(0,0,-1);forward.normalize();ransackEntity??=makeRansackAngel();let distance=4.8,candidate=new THREE.Vector3();while(distance>2.4){candidate.set(camera.position.x+forward.x*distance,1.7,camera.position.z+forward.z*distance);if(!playerHitsSolid(candidate))break;distance-=.6}ransackEntity.position.set(candidate.x,0,candidate.z);ransackEntity.lookAt(camera.position.x,1.65,camera.position.z)}
