 const direct=toPlayer.clone().setY(0).normalize(),side=new THREE.Vector3(-direct.z,0,direct.x),cycle=(time+monster.seed)%4;monster.speedScale=1;
 if(monster.behavior==='sound-hunt'){const moving=keys.KeyW||keys.ArrowUp||keys.KeyS||keys.ArrowDown||keys.KeyA||keys.ArrowLeft||keys.KeyD||keys.ArrowRight,crouched=keys.KeyC||keys.ControlLeft||keys.ControlRight,sprinting=moving&&(keys.ShiftLeft||keys.ShiftRight);if(!moving||crouched){monster.speedScale=0;return new THREE.Vector3()}monster.speedScale=sprinting?1.65:1.15;return direct.addScaledVector(side,Math.sin(time*5+monster.seed)*.12).normalize()}
