 if(monster.behavior==='window-ambush'){if(cycle<1.45)monster.speedScale=.08;else if(cycle<2.15)monster.speedScale=2.05;else monster.speedScale=.42;return direct}
 if(monster.behavior==='false-feint'){if(cycle<1.65)return direct;if(cycle<2.45){monster.speedScale=1.25;return direct.negate()}monster.speedScale=.72;return side.multiplyScalar(monster.turnSign).addScaledVector(direct,.2).normalize()}
