 if(id==='vitamins')usableInventory.vitamins+=5;else if(id==='medkit')usableInventory.medkits+=5;else if(id==='bandage')usableInventory.bandages+=5;else if(id==='energy-drink')usableInventory.energyDrinks+=5;else if(id==='glowstick')usableInventory.glowsticks+=5;else if(id==='wind-up-decoy')usableInventory.decoys+=5;else if(id==='flashlight-battery')usableInventory.batteries+=5;else if(id==='lockpick')usableInventory.lockpicks+=5;else if(id==='matches')usableInventory.matchesBought+=10;else if(id==='gold')usableInventory.adminGold=(usableInventory.adminGold||0)+20;else if(id==='door-handle'){handlePieces=new Set([0,1,2]);localStorage.setItem('cabin-handle-pieces',JSON.stringify([...handlePieces]))}else if(id==='baseball-bat'){batOwned=true;localStorage.setItem('cabin-baseball-bat','true')}else if(['compass','ash-key','batteries','lantern'].includes(id)){cabinSecrets.add(id);localStorage.setItem('cabin-secret-chain',JSON.stringify([...cabinSecrets]))}else if(['sheet','spoon','rope','cutters','baton','hall-key','code','baton-code'].includes(id)){jailbreakItems.add(id);saveJailbreak()}else if(id==='room-assignment'){hotelArrivalItems.add('first-digit');saveHotelArrival()}else if(id==='room304-key'){hotelArrivalItems.add('room304-key');saveHotelArrival()}else if(['flashlight','brochure'].includes(id)){hotelArrivalItems.add(id);saveHotelArrival()}else if(id==='elevator-key'){floorFive??=newFloorFiveRun();floorFive.items.add(id);saveFloorFive()}else if(['sheet-music','grounding-wire','cleaning-rag'].includes(id)){floorTwo??=newFloorTwoRun();if(id==='sheet-music')floorTwo.sheetFound=true;if(id==='grounding-wire')floorTwo.wires=4;if(id==='cleaning-rag')floorTwo.rag=true;saveFloorTwo()}else{hotelRunItems.add(id);saveHotelRun()}
 if(!permanent.has(id))adminGrantedItems.add(id);localStorage.setItem('escape-admin-items',JSON.stringify([...adminGrantedItems]));saveUsableInventory();updateInventory();pickupTone();document.querySelector('#prompt').textContent=`ADMIN GAVE ${inventoryCatalog[id].label.toUpperCase()}`
