function openHotelArrivalGuestbook(){controls.unlock();dlg.classList.add('guestbook-ui');base('ROOM 1 · RECEPTION','THE CHECK-IN LEDGER','Flip through the yellowed pages and find the entry written for you.');const pages=[['1907','M. HARROW · ROOM 112\nChecked in alone. Two shadows followed.'],['1931','THE WEXLER FAMILY · ROOM 208\nFour guests arrived. Five breakfasts ordered.'],['1978','NO LEGIBLE NAME · ROOM 404\nThe ink has been scratched through the paper.'],['TONIGHT',`${hotelArrivalPlayerName} · ROOM __4\nWELCOME BACK. YOUR ROOM HAS BEEN WAITING.`],['UNDATED','All remaining reservations have been cancelled.']];let page=0;const sheet=document.createElement('div'),controlsRow=document.createElement('div'),previousButton=document.createElement('button'),nextButton=document.createElement('button');sheet.className='guestbook-page';controlsRow.className='choices';previousButton.textContent='← PREVIOUS PAGE';nextButton.textContent='NEXT PAGE →';function render(){const entry=pages[page];sheet.innerHTML=`<small>PAGE ${page+1} / ${pages.length} · ${entry[0]}</small><strong>${entry[1].replace('\n','<br>')}</strong>`;previousButton.disabled=page===0;nextButton.disabled=page===pages.length-1;if(page===3&&!hotelArrivalItems.has('guestbook-fragment')){hotelArrivalItems.add('guestbook-fragment');saveHotelArrival();feedback.textContent='YOUR ENTRY READS ROOM __4. ONE DIGIT IS MISSING.'}}previousButton.onclick=()=>{page--;render()};nextButton.onclick=()=>{page++;render()};controlsRow.append(previousButton,nextButton);body.append(sheet,controlsRow);render()}
