 if(part.startsWith('book:')){const shape=part.slice(5),digits={SQUARE:7,TRIANGLE:3,CIRCLE:1,STAR:9};floorFive.librarySeen.add(shape);saveFloorFive();pickupTone();controls.unlock();return message(`${shape} BOOK`,`The number ${digits[shape]} is cut deeply into its spine. ${floorFive.librarySeen.size}/4 books inspected.`)}
