function addHotelNoiseArcMeter(amount){if(!hotelNoiseArc||hotelNoiseArc.room===51||hotelNoiseArc.room===55||hotelNoiseArc.room===59||hotelNoiseArc.room===60||hotelNoiseArc.phase==='failed')return;hotelNoiseArc.meter=THREE.MathUtils.clamp(hotelNoiseArc.meter+amount,0,100);if(hotelNoiseArc.meter>=100)startHotelNoiseArcHunt()}
function startHotelNoiseArcHunt(){if(!hotelNoiseArc||hotelNoiseArc.phase==='hunt')return;hotelNoiseArc.phase='hunt';hotelNoiseArc.huntTimer=7;hotelNoiseArc.drawerHolding=false;hotelNoiseArcEntity.visible=true;hotelNoiseArcEntity.position.set(camera.position.x>0?-7:7,3.3,camera.position.z>0?-8:8);document.body.classList.add('noise-hunt');playNoiseBurst();arcNoiseHud('Signal lost. Crouch and keep moving for seven seconds.')}
function startHotelNoiseArcDrawer(){if(!hotelNoiseArc||hotelNoiseArc.drawerHolding)return;if(hotelRunItems.has(`noise-arc-loot-${hotelNoiseArc.room}`)){document.querySelector('#prompt').textContent='THE DRAWER IS EMPTY';return}if(hotelNoiseArc.phase==='hunt')return addHotelNoiseArcMeter(15);hotelNoiseArc.drawerHolding=true;document.querySelector('#prompt').textContent='KEEP HOLDING E · OPEN SLOWLY'}
