function collectorPhaseCopy(){if(!collector)return['LOST PROPERTY',''];if(collector.complete)return['THE COLLECTOR · ESCAPED','The Collector remains inside Hotel Nocturne.'];if(collector.phase===8)return['PHASE EIGHT · THE ESCAPE','Reach the freight elevator before the Collector catches you.'];if(collector.phase===7)return['PHASE SEVEN · EVERYTHING IS RELEASED','Cross the collapsing collection while the Collector tries to restore it.'];if(collector.phase===6)return['PHASE SIX · THE COLLECTION ROOM','Read the sorting machine and choose RETURN, STORE, or RELEASE.'];if(collector.watchTaken)return['PHASE FIVE · COLLECTION LOCKDOWN','The Pocket Watch cannot be dropped. Trigger your prepared decoys and reach the exit in one trip.'];if(collector.slots.includes('medallion'))return['PHASE FOUR · THE POCKET WATCH','Ring a service bell, circle behind the Collector, and take the Watch from its bag.'];if(collector.slots.includes('key'))return['PHASE THREE · THE SILVER MEDALLION',collector.caseOpen?'Move the Medallion to its exit slot. Press X to drop it before the Collector reaches you.':`Find all three luggage tags, then enter their code at the display case. ${collector.tags.length}/3 found.`];if(collector.carrying==='key'||collector.recovery)return['PHASE TWO · MOVING THE COLLECTION','Move the Brass Key shelf by shelf. Press X to drop it and make the Collector recover it.'];return['PHASE ONE · THE BRASS KEY','Take the Brass Key. The Collector wants its possessions back.']}
function updateCollectorHud(){if(!collector)return;const [phase,copy]=collectorPhaseCopy(),progress=collector.phase>=6?collector.phase===6?0:collector.phase===7?.82:collector.complete?1:.92:collector.slots.length/3;setBossEncounterHud(true,'THE COLLECTOR',phase,copy,progress);document.querySelector('#prompt').textContent=collector.carrying?`${collector.carrying.toUpperCase()} IN HAND · X DROP${collector.carrying==='watch'?' DISABLED':''} · E INTERACT`:'E INTERACT · X DROP CARRIED POSSESSION'}
function collectorShell(label,width=32,depth=32,height=7){resetHotelSideScene();hotelSideScene='collector-'+collector.phase;hotelStairwell=false;collector.boundary=Math.min(width,depth)/2-.7;box('lost property floor',[0,-.14,0],[width,.28,depth],0x2c2925,true);box('lost property ceiling',[0,height,0],[width,.25,depth],0x151312,false);for(const wall of [[0,height/2,-depth/2,width,height,.3],[0,height/2,depth/2,width,height,.3],[-width/2,height/2,0,.3,height,depth],[width/2,height/2,0,.3,height,depth]])box('lost property wall',[wall[0],wall[1],wall[2]],[wall[3],wall[4],wall[5]],0x39332d,true);for(const x of [-10,0,10])light([x,5.7,0],collector.watchTaken?0xa52117:0x9b794b,7,15);chapter.textContent='THE INFINITE HOTEL · LOST PROPERTY';title.textContent=label;description.textContent='Thousands of abandoned possessions fill a department that should not fit beneath the hotel.';objective.textContent='Do not take what belongs to the Collector.';setRoomNumber('LOST PROPERTY');updateCollectorHud();updateInventory(false);setTimeout(()=>controls.lock(),100)}
function makeCollectorDisplay(id,label,pos,color){const mesh=box('collector possession '+id,[pos[0],.65,pos[1]],[id==='key'?.35:id==='medallion'?.6:.5,1,id==='key'?.24:.18],color,false);mesh.rotation.z=id==='key'?.18:0;const hit=interactive([pos[0],1,pos[1]],[1.5,2,1.5],8,'collector','take:'+id);objectLabel(`${label} · E TAKE`,[pos[0],2,pos[1]],.25);collectorItems.set(id,{mesh,hit});return mesh}
function makeCollectorFigure(pos=[0,-13]){collectorEntity=makeAdminMonsterModel('collector');collectorEntity.position.set(pos[0],0,pos[1]);roomGroup.add(collectorEntity);return collectorEntity}
function addCollectorShelves(){for(const x of [-10,-5,0,5,10])for(const z of [-4,5]){box('lost property shelf',[x,1.6,z],[2.2,3.2,6.4],0x49382b,true);for(let level=0;level<3;level++)for(let n=0;n<2;n++)box('stored possession',[x+(n-.5)*.85,.65+level*.95,z+(n?.7:-.8)],[.65,.45,.8],(level+n)%2?0x59402e:0x36393a,false)}}
function addCollectorDecoys(){const positions=[[-13,8],[-7,12],[4,11],[12,8],[-12,-2],[12,-2]];positions.forEach(([x,z],index)=>{if(collector.used.includes(index))return;const prepared=collector.prepared.includes(index),mesh=box('collector decoy '+index,[x,.55,z],[1.6,1.1,1.1],prepared?0x8d713e:0x4b3227,false);interactive([x,1,z],[2.2,2,2],8,'collector','decoy:'+index);objectLabel(collector.watchTaken?(prepared?'DECOY READY · E TRIGGER':'SPENT ROUTE'):(prepared?'DECOY SET · E MOVE':'ABANDONED LUGGAGE · E SET'),[x,1.9,z],.2);collectorDecoys.push({index,mesh,position:new THREE.Vector3(x,0,z)})})}
function addCollectorExitSlots(){box('collection lock',[0,2,-15.65],[8,4,.35],0x30373a,false);[['key',-2.4],['medallion',0],['watch',2.4]].forEach(([id,x])=>{const filled=collector.slots.includes(id);box(id+' slot',[x,2,-15.4],[1.35,1.35,.22],filled?0xc39a4f:0x111315,false);interactive([x,2,-14.8],[1.6,2,1.2],8,'collector','slot:'+id);objectLabel(`${id.toUpperCase()} ${filled?'✓':'—'}`,[x,3.2,-14.6],.22)})}
function buildCollectorDepartment(){collectorShell('THE LOST PROPERTY DEPARTMENT');document.body.classList.toggle('collector-lockdown',collector.watchTaken);addCollectorShelves();addCollectorDecoys();addCollectorExitSlots();box('old elevator',[0,2,15.65],[6,4,.3],0x414548,false);const keyPos=collector.positions.key||[-11,-9],keyVisible=!collector.recovery||collector.recovery.id!=='key'||collector.recovery.stage==='fetch';if(!collector.slots.includes('key')&&collector.carrying!=='key'&&keyVisible)makeCollectorDisplay('key','BRASS KEY',keyPos,0xc39a4f);if(collector.slots.includes('key')&&!collector.slots.includes('medallion')){for(const [index,x,z,digit] of [[0,-12,10,3],[1,9,9,0],[2,-12,-7,4]])if(!collector.tags.includes(index)){box('numbered luggage tag',[x,1,z],[.7,1,.15],0xc5a66a,false);interactive([x,1,z],[1.5,2,1.5],8,'collector','tag:'+index);objectLabel(`TAG ${index+1} · E READ`,[x,2,z],.21)}box('medallion display case',[11,1.2,-9],[3,2.4,1.4],collector.caseOpen?0x5c4732:0x20272b,true);interactive([11,1.4,-8],[3.4,2.8,1.5],8,'collector','case');objectLabel(collector.caseOpen?'CASE OPEN':'3-DIGIT DISPLAY CASE · E',[11,3,-7.9],.25);const medallionVisible=!collector.recovery||collector.recovery.id!=='medallion'||collector.recovery.stage==='fetch';if(collector.caseOpen&&collector.carrying!=='medallion'&&medallionVisible&&!collector.slots.includes('medallion'))makeCollectorDisplay('medallion','SILVER MEDALLION',collector.positions.medallion||[11,-9],0xb9c2c5)}
 if(collector.slots.includes('medallion')&&!collector.watchTaken){for(const [index,x,z] of [[0,-12,11],[1,12,5],[2,-11,-9]]){const bell=box('service bell '+index,[x,.7,z],[.8,.7,.8],0xb78c43,false);interactive([x,1,z],[1.8,2,1.8],8,'collector','bell:'+index);objectLabel(`SERVICE BELL ${index+1} · E RING`,[x,1.8,z],.2);collectorBells.push({index,mesh:bell,position:new THREE.Vector3(x,0,z)})}}
 makeCollectorFigure([0,-12]);if(collector.slots.includes('medallion')&&!collector.watchTaken){collectorWatchHit=interactive([0,1.6,-12],[1.7,3,1.7],8,'collector','take-watch');objectLabel('POCKET WATCH · ON COLLECTION BAG',[0,3.8,-12],.22)}camera.position.set(0,1.7,13);camera.lookAt(0,1.6,-6);updateCollectorHud();saveCollector()}
function startCollector(fresh=false){floorOne=null;floorTwo=null;clockmaker=null;drowned=null;pursuer=null;collector=fresh?newCollectorRun():(loadCollector()||newCollectorRun());collector.dying=false;if(collector.complete)return buildCollectorAftermath();if(collector.phase===6)return buildCollectorCollectionRoom();if(collector.phase===7)return buildCollectorRelease();if(collector.phase===8)return buildCollectorEscape();buildCollectorDepartment();if(fresh){controls.unlock();message('BOSS 1 · THE COLLECTOR','The LOST PROPERTY elevator descends into a storage department containing everything Hotel Nocturne has taken. The Noise Meter is offline here.') }}
function takeCollectorPossession(id){if(collector.carrying)return document.querySelector('#prompt').textContent='YOUR HANDS ARE ALREADY FULL';if(id==='medallion'&&!collector.caseOpen)return;collector.carrying=id;collector.recovery=null;if(id==='key')collector.phase=Math.max(2,collector.phase);collectorItems.get(id)?.mesh.removeFromParent();collectorItems.get(id)?.hit.removeFromParent();collectorItems.delete(id);saveCollector();pickupTone();updateCollectorHud()}
function dropCollectorPossession(){if(!collector?.carrying)return;if(collector.carrying==='watch')return document.querySelector('#prompt').textContent='THE POCKET WATCH CANNOT BE DROPPED · KEEP RUNNING';const id=collector.carrying,pos=[THREE.MathUtils.clamp(camera.position.x,-13,13),THREE.MathUtils.clamp(camera.position.z,-13,13)];collector.carrying=null;collector.positions[id]=pos;collector.recovery={id,stage:'fetch',drop:pos,origin:id==='key'?[-11,-9]:[11,-9]};makeCollectorDisplay(id,id==='key'?'BRASS KEY':'SILVER MEDALLION',pos,id==='key'?0xc39a4f:0xb9c2c5);saveCollector();document.querySelector('#prompt').textContent=`${id.toUpperCase()} DROPPED · THE COLLECTOR IS COMING TO RECOVER IT`}
function openCollectorCase(){if(collector.caseOpen)return;controls.unlock();base('THE COLLECTOR · PHASE THREE','NUMBERED LUGGAGE TAGS',collector.tags.length<3?`Find all three tags first. ${collector.tags.length}/3 recovered.`:'Enter the luggage-tag digits in order.');if(collector.tags.length<3)return;const readout=document.createElement('div'),wrap=document.createElement('div');readout.className='handle-count';wrap.className='choices';let code='';readout.textContent='—';for(let digit=0;digit<=9;digit++){const button=document.createElement('button');button.textContent=digit;button.onclick=()=>{code=(code+digit).slice(-3);readout.textContent=code.padEnd(3,'—');if(code.length===3){if(code==='304'){collector.caseOpen=true;saveCollector();feedback.textContent='DISPLAY CASE UNLOCKED';setTimeout(()=>{dlg.close();buildCollectorDepartment()},550)}else{code='';feedback.textContent='THE CASE REJECTS THE CODE';setTimeout(()=>readout.textContent='—',350)}}};wrap.append(button)}body.append(readout,wrap)}
function collectorBehind(){if(!collectorEntity)return false;const towardPlayer=new THREE.Vector3(camera.position.x,0,camera.position.z).sub(collectorEntity.position).normalize(),forward=new THREE.Vector3();collectorEntity.getWorldDirection(forward);forward.y=0;return forward.normalize().dot(towardPlayer)<-.2}
function handleCollector(part){if(!collector||collector.dying)return;if(part.startsWith('take:'))return takeCollectorPossession(part.slice(5));if(part.startsWith('slot:')){const id=part.slice(5);if(collector.slots.includes(id))return;if(collector.carrying!==id)return document.querySelector('#prompt').textContent=`THIS SLOT REQUIRES THE ${id.toUpperCase()}`;collector.carrying=null;collector.slots.push(id);collector.recovery=null;if(id==='key')collector.phase=3;if(id==='medallion')collector.phase=4;if(id==='watch'){collector.phase=6;saveCollector();playPurgeCrash();return buildCollectorCollectionRoom()}saveCollector();pickupTone();return buildCollectorDepartment()}
 if(part.startsWith('tag:')){const index=Number(part.slice(4));if(!collector.tags.includes(index)){collector.tags.push(index);saveCollector();pickupTone()}const digits=[3,0,4];controls.unlock();return message(`LUGGAGE TAG ${index+1}`,`A faded number is still readable: ${digits[index]}. The full case code follows the tag order.`)}
 if(part==='case')return openCollectorCase();
 if(part.startsWith('decoy:')){const index=Number(part.slice(6)),entry=collectorDecoys.find(item=>item.index===index);if(collector.watchTaken){if(!collector.prepared.includes(index)||collector.used.includes(index))return document.querySelector('#prompt').textContent='THIS DECOY WAS NOT PREPARED';collector.used.push(index);collector.distraction=entry?.position.toArray()||[0,0,0];collector.distractionTimer=2.8;if(entry)entry.mesh.visible=false;pickupTone();document.querySelector('#prompt').textContent='DECOY THROWN · THE COLLECTOR CHANGES COURSE'}else{const at=collector.prepared.indexOf(index);if(at>=0){collector.prepared.splice(at,1);if(entry)entry.mesh.material.color.setHex(0x4b3227);document.querySelector('#prompt').textContent='DECOY REMOVED FROM ESCAPE ROUTE'}else{collector.prepared.push(index);if(entry)entry.mesh.material.color.setHex(0x8d713e);document.querySelector('#prompt').textContent='DECOY PREPARED FOR THE POCKET WATCH ESCAPE'}}saveCollector();return}
 if(part.startsWith('bell:')){const index=Number(part.slice(5)),bell=collectorBells.find(item=>item.index===index);collector.distraction=bell?.position.toArray()||[0,0,0];collector.distractionTimer=5;saveCollector();playPurgeCrash();return document.querySelector('#prompt').textContent='SERVICE BELL RINGS · CIRCLE BEHIND THE COLLECTOR'}
 if(part==='take-watch'){if(collector.distractionTimer<=0)return document.querySelector('#prompt').textContent='RING A SERVICE BELL FIRST';if(camera.position.distanceTo(collectorEntity.position)>2.3||!collectorBehind())return document.querySelector('#prompt').textContent='GET DIRECTLY BEHIND THE COLLECTION BAG';collector.watchTaken=true;collector.carrying='watch';collector.phase=5;collector.used=[];collector.distractionTimer=0;collector.distraction=null;collectorWatchHit?.removeFromParent();interactables=interactables.filter(item=>item!==collectorWatchHit);collectorWatchHit=null;document.body.classList.add('collector-lockdown');saveCollector();horrorStinger();return updateCollectorHud()}
 if(part.startsWith('lever:')){const choice=part.slice(6);if(choice!=='release'){collector.leverAttempts++;collectorEntity.position.z+=3.2;saveCollector();horrorStinger();objective.textContent=`${choice.toUpperCase()} reroutes the machine. The Collector is closer. Choose again.`;return}collector.released=true;collector.phase=7;saveCollector();playPurgeCrash();return buildCollectorRelease()}
 if(part==='release-exit'){collector.phase=8;saveCollector();return buildCollectorEscape()}if(part==='escape-elevator')return finishCollector();if(part==='return-room140'){collector=null;floorTwo=newFloorTwoRun();floorTwo.phase=19;return buildFloorTwoSafe()}}
function buildCollectorCollectionRoom(){collector.phase=6;collectorShell('THE COLLECTION ROOM',26,26,7);for(const [x,z,color] of [[-8,4,0x504131],[0,4,0x3e2923],[8,4,0x4d4a43],[-8,-4,0x303a43],[8,-4,0x57372e]])box('private collection cabinet',[x,1.8,z],[4,3.6,2],color,true);box('mechanical sorting machine',[0,1.7,-8],[8,3.4,2.2],0x343a3b,true);[['return',-5],['store',0],['release',5]].forEach(([id,x])=>{box(id+' lever',[x,1.3,-5.8],[.4,1.8,.4],id==='release'?0xb28a43:0x606569,false).rotation.z=.35;interactive([x,1.5,-5.5],[2,2.6,1.8],8,'collector','lever:'+id);objectLabel(id.toUpperCase(),[x,3,-5.4],.28)});makeCollectorFigure([0,11-collector.leverAttempts*3.2]);camera.position.set(0,1.7,10);camera.lookAt(0,1.6,-7);description.textContent='Guestbooks, staff badges, photographs, and keys from different decades surround a sorting machine.';objective.textContent='The mechanism needs the command that frees property rather than returning or storing it.';updateCollectorHud();saveCollector()}
function buildCollectorRelease(){collector.phase=7;collectorShell('EVERYTHING IS RELEASED');document.body.classList.add('collector-release');for(let n=0;n<30;n++){const x=(Math.random()-.5)*26,z=(Math.random()-.5)*25;box('released possession '+n,[x,.15+Math.random()*.25,z],[.35+Math.random()*1.1,.25+Math.random()*.45,.35+Math.random()*1.1],n%3?0x59402f:0xa18043,false)}for(const [index,z] of [[0,8],[1,0],[2,-8]]){const cart=box('rolling luggage cart '+index,[index%2?-13:13,.7,z],[2.3,1.4,1.5],0x8b6e42,false);collectorCarts.push({mesh:cart,direction:index%2?1:-1,cooldown:0})}makeCollectorFigure([9,0]);interactive([0,1.7,-14.7],[4,3.5,1.2],8,'collector','release-exit');objectLabel('FREIGHT CORRIDOR · E ESCAPE',[0,3.8,-14.5],.3);camera.position.set(0,1.7,13);camera.lookAt(0,1.6,-10);description.textContent='Every compartment opens at once. The Collector abandons the player and frantically reaches for falling property.';objective.textContent='Avoid rolling luggage carts and reach the freight corridor.';updateCollectorHud();saveCollector()}
function buildCollectorEscape(){collector.phase=8;collectorShell('THE BAGGAGE CORRIDOR',12,32,6);collector.boundary=15.3;for(const [x,z] of [[-3,8],[3,4],[-3,0],[3,-5]])box('corridor baggage pile',[x,.8,z],[3,1.6,2.2],0x50382a,true);box('freight elevator doors',[0,2,-15.5],[5,4,.35],0x4a5052,false);interactive([0,1.8,-14.7],[5,3.6,1.2],8,'collector','escape-elevator');objectLabel('FREIGHT ELEVATOR · E ENTER',[0,4,-14.4],.3);makeCollectorFigure([0,13]);camera.position.set(0,1.7,10);camera.lookAt(0,1.5,-11);description.textContent='The Collector finally abandons the released objects. Keys strike together behind you as it enters the narrow corridor.';objective.textContent='No more puzzles. Run to the freight elevator.';updateCollectorHud();saveCollector()}
function finishCollector(){collector.complete=true;collector.phase=9;collector.carrying=null;saveCollector();saveHotelProgress('collector-escaped');buildCollectorAftermath();controls.unlock();message('THE COLLECTOR · ESCAPED',`The elevator descends. On its floor is an old Hotel Nocturne luggage tag bearing ${hotelArrivalPlayerName} — ROOM 304. The Collector owned something of yours before you entered Lost Property.`)}
function buildCollectorAftermath(){collectorShell('THE FREIGHT ELEVATOR',12,12,5);collector.complete=true;box('closed freight doors',[0,2,-5.8],[5,4,.3],0x444b4e,false);box('luggage tag',[0,.08,-1],[1.2,.08,.7],0xd0b273,false);interactive([0,.5,-1],[2,1.2,2],8,'collector','return-room140');objectLabel(`${hotelArrivalPlayerName} · ROOM 304`,[0,1.3,-1],.33);camera.position.set(0,1.7,3.5);camera.lookAt(0,.5,-1);description.textContent='The elevator descends while the Collector remains above, alive and surrounded by everything the hotel took.';objective.textContent='The luggage tag is yours. Press E on it to return to Room 140.';updateCollectorHud();saveCollector()}
function failCollector(reason){if(adminPreventDeath(reason))return;if(!collector||collector.dying)return;collector.dying=true;if(collector.phase===8){collector.carrying=null}else if(collector.watchTaken){collector.watchTaken=false;collector.carrying=null;collector.phase=4;collector.used=[]}else if(collector.carrying){const id=collector.carrying;collector.carrying=null;collector.positions[id]=id==='key'?[-11,-9]:[11,-9];collector.recovery=null}saveCollector();controls.unlock();horrorStinger();const blackout=document.querySelector('#blackout');blackout.querySelector('span').textContent=reason;blackout.classList.add('show');setTimeout(()=>{collector.dying=false;collector.phase===8?buildCollectorEscape():buildCollectorDepartment();blackout.classList.remove('show');blackout.querySelector('span').textContent='You wake inside the cabin.'},950)}
function updateCollector(dt,time){if(!collector||!hotelSideScene.startsWith('collector-')||collector.complete)return;if(collector.distractionTimer>0){collector.distractionTimer=Math.max(0,collector.distractionTimer-dt);if(!collector.distractionTimer)collector.distraction=null}if(collector.phase===7){for(const cart of collectorCarts){cart.cooldown=Math.max(0,cart.cooldown-dt);cart.mesh.position.x+=cart.direction*dt*7;if(Math.abs(cart.mesh.position.x)>13)cart.direction*=-1;if(cart.cooldown<=0&&Math.abs(cart.mesh.position.x-camera.position.x)<1.5&&Math.abs(cart.mesh.position.z-camera.position.z)<1.2){cart.cooldown=2;setStability(stability-18);camera.position.z+=2;horrorStinger()}}if(collectorEntity){const target=collectorDecoys[Math.floor(time)%Math.max(1,collectorDecoys.length)]?.position||new THREE.Vector3(8,0,0);collectorEntity.position.lerp(target,.012);collectorEntity.rotation.y+=dt*2}return}if(!collectorEntity)return;if(collectorWatchHit){collectorWatchHit.position.copy(collectorEntity.position);collectorWatchHit.position.y=1.6}
 let target=null,speed=collector.watchTaken?4.5:collector.phase===8?4.8:3.05;if(collector.distraction)target=new THREE.Vector3(collector.distraction[0],0,collector.distraction[2]);else if(collector.carrying)target=new THREE.Vector3(camera.position.x,0,camera.position.z);else if(collector.recovery){const point=collector.recovery.stage==='fetch'?collector.recovery.drop:collector.recovery.origin;target=new THREE.Vector3(point[0],0,point[1])}else if(collector.phase===8)target=new THREE.Vector3(camera.position.x,0,camera.position.z);else target=new THREE.Vector3(Math.sin(time*.22)*11,0,Math.cos(time*.18)*10);
 const direction=target.clone().sub(collectorEntity.position);direction.y=0;if(direction.length()>.18)collectorEntity.position.add(direction.normalize().multiplyScalar(speed*dt));collectorEntity.lookAt(target.x,1.5,target.z);collectorEntity.rotation.z=Math.sin(time*6)*.025;if(collector.recovery&&direction.length()<.55){if(collector.recovery.stage==='fetch'){collector.recovery.stage='return';collectorItems.get(collector.recovery.id)?.mesh.removeFromParent();collectorItems.get(collector.recovery.id)?.hit.removeFromParent();collectorItems.delete(collector.recovery.id)}else{collector.positions[collector.recovery.id]=collector.recovery.origin;collector.recovery=null;saveCollector();buildCollectorDepartment();return}}const distance=Math.hypot(collectorEntity.position.x-camera.position.x,collectorEntity.position.z-camera.position.z);if((collector.carrying||collector.phase===8)&&distance<1.2)failCollector(collector.watchTaken?'THE COLLECTOR RECLAIMED THE POCKET WATCH':'THE COLLECTOR CAUGHT YOU WITH ITS PROPERTY')}
function newClockmakerRun(){return{phase:1,lowerLocks:[],upperLocks:[],clocks:[{hour:10,minute:45,locked:false},{hour:11,minute:30,locked:false},{hour:9,minute:45,locked:false},{hour:11,minute:45,locked:false}],brakes:[],masterLocks:[],masterHour:11,masterMinute:55,rhythmTime:0,lastTick:-1,lastAttack:-1,lastImpact:-1,reverseAnchorZ:null,damageCooldown:0,restartTimer:9,restartElapsed:0,endReveal:0,complete:false,dying:false,boundary:15.2}}
function saveClockmaker(){if(clockmaker)sessionStorage.setItem('infinite-hotel-clockmaker',JSON.stringify(clockmaker))}
function loadClockmaker(){try{const value=JSON.parse(sessionStorage.getItem('infinite-hotel-clockmaker')||'null');return value?{...newClockmakerRun(),...value}:null}catch{return null}}
function clockmakerProgress(){if(!clockmaker)return 0;if(clockmaker.complete)return 1;if(clockmaker.phase===1)return clockmaker.lowerLocks.length/3;if(clockmaker.phase===2)return clockmaker.upperLocks.length/2;if(clockmaker.phase===3)return clockmaker.clocks.filter(item=>item.locked).length/4;if(clockmaker.phase===4)return .46;if(clockmaker.phase===5)return(.48+clockmaker.brakes.length*.09);if(clockmaker.phase===6)return(.75+clockmaker.masterLocks.length*.05);return .94}
function clockmakerPhaseCopy(){const copies={1:['PHASE ONE · FOLLOW THE RHYTHM','Activate all three lower mechanisms when their hand reaches twelve. The machinery changes on every fourth DING.'],2:['PHASE TWO · THE CLOCK FACE CHASE','Run while reading the face: 12 stay in an alcove, 3 stay on a platform above lava, 6 dodge pendulums, 9 move backward.'],3:['PHASE THREE · THE FOUR CLOCKS','Set every clock to 12:00. Looking at the Clockmaker slows each tick-step.'],4:['PHASE FOUR · THE BROKEN CLOCK','The tower is malfunctioning. Cross the irregular machinery and begin the climb.'],5:['PHASE FIVE · CLOCK TOWER CLIMB','Climb the maintenance route and pull all three emergency brakes.'],6:['PHASE SIX · THE MASTER CLOCK','Slow both hands, stop the clock at exactly 12:00, then engage the permanent lock.'],7:['PHASE SEVEN · ESCAPE THE FROZEN TOWER',clockmaker?.restartTimer>0?'Cross the stopped machinery before the Clockmaker restarts.':'GET OUT. The ticks are accelerating behind you.']};return clockmaker?.complete?['THE CLOCKMAKER · OUT OF TIME','The tower was stopped for one minute—not forever.']:copies[clockmaker?.phase]||copies[1]}
function clockmakerDisplayTime(){if(!clockmaker)return'12:00';if(clockmaker.complete)return clockmaker.endReveal>=2?'12:01':'12:00';if(clockmaker.phase===6){const hour=clockmaker.masterHour===0?12:clockmaker.masterHour;return`${String(hour).padStart(2,'0')}:${String(Math.floor(clockmaker.masterMinute)).padStart(2,'0')}`}if(clockmaker.phase===2)return['12 · BELL','03 · GEARS','06 · PENDULUM','09 · REVERSE'][Math.max(0,clockmaker.lastAttack)]||'12 · BELL';const beat=Math.floor(clockmaker.rhythmTime)%4;return beat===3?'DING!':`TICK ${beat+1} / 4`}
function setClockmakerHud(){if(!clockmaker)return;document.body.classList.add('boss-encounter');document.querySelector('#boss-hud')?.classList.remove('active');document.querySelector('#noise-hud')?.classList.remove('active','danger');const hud=document.querySelector('#clockmaker-hud'),[phase,copy]=clockmakerPhaseCopy();hud?.classList.add('active');document.querySelector('#clockmaker-phase').textContent=phase;document.querySelector('#clockmaker-instruction').textContent=copy;document.querySelector('#clockmaker-progress').style.transform=`scaleX(${THREE.MathUtils.clamp(clockmakerProgress(),0,1)})`;document.querySelector('#clockmaker-time').textContent=clockmakerDisplayTime();let minuteAngle=(clockmaker.rhythmTime%4)/4*360,hourAngle=minuteAngle/12;if(clockmaker.phase===2){minuteAngle=[0,90,180,270][Math.max(0,clockmaker.lastAttack)]||0;hourAngle=minuteAngle}if(clockmaker.phase===6){minuteAngle=clockmaker.masterMinute/60*360;hourAngle=(clockmaker.masterHour%12+clockmaker.masterMinute/60)/12*360}document.querySelector('#clockmaker-minute-hand').style.transform=`rotate(${minuteAngle}deg)`;document.querySelector('#clockmaker-hour-hand').style.transform=`rotate(${hourAngle}deg)`}
function clockmakerShell(label,width=32,depth=32,height=9){resetHotelSideScene();hotelSideScene='clockmaker-'+clockmaker.phase;hotelStairwell=false;clockmaker.boundary=Math.max(width,depth)/2-.7;box('clock tower floor',[0,-.14,0],[width,.28,depth],0x29251f,true);box('clock tower ceiling',[0,height,0],[width,.25,depth],0x15130f,false);for(const wall of [[0,height/2,-depth/2,width,height,.3],[0,height/2,depth/2,width,height,.3],[-width/2,height/2,0,.3,height,depth],[width/2,height/2,0,.3,height,depth]])box('clock tower wall',[wall[0],wall[1],wall[2]],[wall[3],wall[4],wall[5]],0x433a2c,true);for(const [x,z] of [[-11,-11],[0,-11],[11,-11],[-11,2],[11,2],[-11,11],[0,11],[11,11]]){const face=new THREE.Mesh(new THREE.CircleGeometry(.72,20),mat(0xcfbd8a,.35));face.position.set(x,4,z);if(Math.abs(z)>10)face.rotation.y=z>0?Math.PI:0;else{face.rotation.y=x>0?-Math.PI/2:Math.PI/2}roomGroup.add(face)}for(const x of [-10,0,10])light([x,7,0],0xc29b52,7,15);chapter.textContent='THE INFINITE HOTEL · CLOCK TOWER';title.textContent=label;description.textContent='Hundreds of clocks surround moving gears, narrow maintenance paths, chains, bells, and pendulums.';objective.textContent='The Clockmaker controls the tower through timing.';setRoomNumber('CLOCK TOWER');setClockmakerHud();updateInventory(false);setTimeout(()=>controls.lock(),100)}
function addClockGear(name,pos,radius=2,color=0x9b7335){const group=new THREE.Group(),ring=new THREE.Mesh(new THREE.TorusGeometry(radius,.22,8,28),mat(color,.28,0x241504));group.add(ring);for(let n=0;n<14;n++){const tooth=box(name+' tooth',[0,0,0],[.5,.28,.5],color,false);tooth.removeFromParent();const angle=n/14*Math.PI*2;tooth.position.set(Math.cos(angle)*radius,Math.sin(angle)*radius,0);tooth.rotation.z=angle;group.add(tooth)}group.position.set(...pos);roomGroup.add(group);clockmakerGears.push(group);return group}
function addClockPendulum(x,z,height=6){const group=new THREE.Group(),rod=new THREE.Mesh(new THREE.BoxGeometry(.18,height,.16),mat(0x8e6b36,.28)),weight=new THREE.Mesh(new THREE.SphereGeometry(.55,14,10),mat(0xb78e45,.25));rod.position.y=-height/2;weight.position.y=-height;group.add(rod,weight);group.position.set(x,height+1,z);roomGroup.add(group);clockmakerPendulums.push({mesh:group,x,z,range:6,phase:Math.random()*2});return group}
function addWorkingClock(name,pos,radius=1.5){const group=new THREE.Group(),face=new THREE.Mesh(new THREE.CircleGeometry(radius,28),mat(0xd4c79c,.32)),rim=new THREE.Mesh(new THREE.TorusGeometry(radius,.12,8,30),mat(0xa77b36,.24)),hourPivot=new THREE.Group(),minutePivot=new THREE.Group(),hour=new THREE.Mesh(new THREE.BoxGeometry(.08,radius*.58,.05),mat(0x1b1812)),minute=new THREE.Mesh(new THREE.BoxGeometry(.055,radius*.82,.05),mat(0x392813));hour.position.y=radius*.29;minute.position.y=radius*.41;hourPivot.add(hour);minutePivot.add(minute);group.add(face,rim,hourPivot,minutePivot);group.position.set(...pos);roomGroup.add(group);clockmakerClocks.push({name,group,hourPivot,minutePivot});return clockmakerClocks.at(-1)}
function makeClockmakerFigure(pos=[0,-10],broken=false){clockmakerEntity=makeAdminMonsterModel('clockmaker');clockmakerEntity.position.set(pos[0],pos[1]||0,pos[2]??-10);if(broken){clockmakerEntity.rotation.z=.12;clockmakerEntity.userData.clockHands?.forEach((hand,index)=>{if(index===0)hand.visible=false;else hand.rotation.z=2.2})}roomGroup.add(clockmakerEntity);return clockmakerEntity}
function clockPlatform(name,pos,size,color=0x4a4134){const mesh=box(name,pos,size,color,false);hotelStairPlatforms.push({x:pos[0],z:pos[2],halfX:size[0]/2,halfZ:size[2]/2,rotation:0,top:pos[1]+size[1]/2,mesh});clockmakerPlatforms.push(mesh);return mesh}
function buildClockmakerRhythm(){clockmaker.phase=1;clockmakerShell('THE SILENT CLOCK TOWER',32,34,10);addClockPendulum(0,2,6);for(const [x,z] of [[-8,-3],[0,-5],[8,-3]]){const gear=addClockGear('lower rotating gear',[x,1.25,z],2.1);gear.rotation.x=Math.PI/2}for(const [index,x,z] of [[0,-10,-10],[1,0,-12],[2,10,-10]]){box('lower clock mechanism',[x,1,z],[3,2,1.5],0x584731,true);interactive([x,1.4,z+1],[3.4,2.6,1.5],8,'clockmaker','lower-lock:'+index);objectLabel(clockmaker.lowerLocks.includes(index)?`MECHANISM ${index+1} · LOCKED`:`MECHANISM ${index+1} · E AT 12`,[x,2.8,z+1],.23)}box('clockmaker control balcony',[0,5,-15],[12,.4,4],0x4b4132,false);makeClockmakerFigure([0,5,-14]);camera.position.set(0,1.7,14);camera.lookAt(0,2,-9);description.textContent='Every clock is silent until the Clockmaker closes a pocket watch, says “You’re late,” and pulls the master lever. TICK. TICK. TICK. DING.';objective.textContent='Cross the lower machinery and lock all three mechanisms when their hands reach twelve.';setClockmakerHud();saveClockmaker()}
function buildClockmakerFace(){clockmaker.phase=2;clockmakerShell('THE CLOCK FACE CHASE',22,52,10);clockmaker.boundary=25.3;clockmakerLavaFloor=box('clock face lava floor',[0,.015,0],[21.4,.05,51.4],0x4a1208,false);clockmakerLavaFloor.material.emissive.setHex(0xe12d08);clockmakerLavaFloor.material.emissiveIntensity=0;clockmakerLavaFloor.material.transparent=true;clockmakerLavaFloor.material.opacity=.05;for(const [index,x,z] of [[0,-7,13],[1,7,5],[2,-7,-5],[3,7,-13]]){const gear=addClockGear('chase wall gear '+index,[x,3,z],2.1);gear.rotation.y=Math.PI/2}for(const [index,x,z] of [[0,0,16],[1,-4,6],[2,4,-4],[3,-4,-14],[4,4,-22]]){const platform=box('clock chase safe platform '+index,[x,.15,z],[4.8,.3,5.2],0x665942,false);clockmakerPlatforms.push(platform);objectLabel('STABLE PLATFORM',[x,1,z],.16)}for(const z of [17,7,-3,-13])for(const x of [-8.8,8.8]){box('clock chase alcove floor',[x,.12,z],[3.8,.25,5.4],0x39342b,false);box('clock chase alcove shield',[x>0?10.55:-10.55,2,z],[.45,4,5.8],0x504536,true);box('clock chase alcove lip',[x,2,z-2.7],[3.8,4,.3],0x504536,true);clockmakerAlcoves.push({x,z,halfX:2.1,halfZ:2.8});objectLabel('ALCOVE · STAY INSIDE',[x,4.3,z],.17)}for(const [x,z] of [[-5,11],[5,0],[-5,-11]])addClockPendulum(x,z,6);for(const [index,x,z] of [[0,-6,2],[1,6,-19]]){box('chase clock mechanism',[x,1,z],[3,2,1.5],0x5e4b31,true);interactive([x,1.4,z+1],[3.5,2.8,1.4],8,'clockmaker','upper-lock:'+index);objectLabel(clockmaker.upperLocks.includes(index)?`CHASE LOCK ${index+1} · SET`:`CHASE LOCK ${index+1} · E AT 12`,[x,2.9,z+1],.22)}box('clock chase exit',[0,2,-25.7],[5,4,.3],0x493b29,false);objectLabel('KEEP RUNNING · SET BOTH LOCKS',[0,4.2,-25],.25);makeClockmakerFigure([0,0,28.5]);camera.position.set(0,1.7,21.5);camera.lookAt(0,1.7,-16);description.textContent='The brass face controls a chase through the tower. The Clockmaker advances from behind while each hour changes the rule of the corridor.';objective.textContent='Run toward both clock locks. At 12 stay inside an alcove, at 3 remain on a platform above lava, at 6 dodge pendulums, and at 9 retreat backward.';setClockmakerHud();saveClockmaker()}
function buildClockmakerFourClocks(){clockmaker.phase=3;clockmakerShell('THE FOUR CLOCKS',34,34,9);const specs=[[-11,3,-16,0],[-4,3,-16,0],[4,3,-16,0],[11,3,-16,0]];specs.forEach(([x,y,z],index)=>{const clock=addWorkingClock('chamber clock '+index,[x,y,z],2.1),state=clockmaker.clocks[index];clock.hourPivot.rotation.z=-state.hour/12*Math.PI*2;clock.minutePivot.rotation.z=-state.minute/60*Math.PI*2;interactive([x-1,1.1,-14.8],[1.7,2,1.4],8,'clockmaker','clock-hour:'+index);interactive([x+1,1.1,-14.8],[1.7,2,1.4],8,'clockmaker','clock-minute:'+index);objectLabel('HOUR',[x-1,2,-14.6],.14);objectLabel('MINUTE',[x+1,2,-14.6],.14);objectLabel(state.locked?`CLOCK ${index+1} · 12:00 LOCKED`:`${String(state.hour).padStart(2,'0')}:${String(state.minute).padStart(2,'0')} · HOUR / MIN`,[x,5.8,-15],.21)});for(const x of [-8,0,8])box('four clock cover',[x,1.3,-3],[2.5,2.6,2.5],0x42392d,true);makeClockmakerFigure([0,0,-10]);camera.position.set(0,1.7,13);camera.lookAt(0,2,-12);description.textContent='The Clockmaker advances several feet only when the tower ticks. Looking directly at him slows each step.';objective.textContent='Use the HOUR and MINUTE controls beneath each face to set all four clocks to midnight.';setClockmakerHud();saveClockmaker()}
function buildClockmakerBroken(){clockmaker.phase=4;clockmakerShell('THE BROKEN CLOCK',32,34,10);document.body.classList.add('clockmaker-broken');for(const [index,x,z] of [[0,-8,5],[1,0,0],[2,8,-5]]){const gear=addClockGear('malfunction gear '+index,[x,1.4,z],2.5,index%2?0x80552e:0xa77a37);gear.rotation.x=Math.PI/2}for(const [x,z] of [[-7,-1],[7,-8]])addClockPendulum(x,z,6);for(const [x,z] of [[-10,9],[10,4],[-10,-4],[10,-10]])box('broken tower stable platform',[x,.15,z],[5,.3,5],0x50483b,false);box('tower climb maintenance door',[0,2,-16.6],[5,4,.3],0x4b3927,false);interactive([0,1.8,-15.7],[5,3.6,1.4],8,'clockmaker','climb-start');objectLabel('STOP THE MASTER CLOCK · CLIMB',[0,4.2,-15.5],.3);makeClockmakerFigure([0,0,13],true);camera.position.set(0,1.7,14);camera.lookAt(0,1.7,-12);description.textContent='The face cracks, one hand falls away, and the remaining hand spins without rhythm. The tower begins choosing its own timing.';objective.textContent='Cross the malfunctioning floor and reach the maintenance climb.';setClockmakerHud();saveClockmaker()}
function addClockStairFlight(axis,start,count,stepVector,rise=.24){for(let n=0;n<count;n++){const pos=[start[0]+stepVector[0]*n,start[1]+rise*n,start[2]+stepVector[2]*n];clockPlatform('clock tower stair',pos,[2.8,.2,1.15],0x51483a)}}
function buildClockmakerClimb(){clockmaker.phase=5;clockmakerShell('THE CLOCK TOWER CLIMB',24,28,18);hotelStairwell=true;hotelStairPlatforms=[];clockmaker.boundary=13.2;clockPlatform('climb start',[0,.05,10],[10,.2,5]);addClockStairFlight('z',[-6,.08,9],16,[0,0,-.55]);clockPlatform('brake one landing',[-6,3.82,-1],[7,.3,4]);addClockStairFlight('x',[-5,3.95,-3],17,[.75,0,0]);clockPlatform('brake two landing',[7,7.78,-3],[5,.3,5]);addClockStairFlight('z',[7,7.9,-4],16,[0,0,-.55]);clockPlatform('brake three landing',[7,11.62,-13],[8,.3,4]);clockPlatform('master threshold',[0,11.62,-13],[8,.3,4]);for(const [index,x,y,z] of [[0,-8,4.8,-1],[1,9,8.7,-3],[2,5,12.6,-13]]){box('emergency brake '+index,[x,y,z],[.45,1.8,.45],0xb18a47,false).rotation.z=.45;interactive([x,y,z],[2,2.5,2],8,'clockmaker','brake:'+index);objectLabel(clockmaker.brakes.includes(index)?`BRAKE ${index+1} · LOCKED`:`BRAKE ${index+1} · E PULL`,[x,y+1.5,z],.22)}box('master chamber hatch',[0,13.4,-15.2],[5,3.5,.3],0x463827,false);interactive([0,13,-14.3],[5,3.5,1.4],8,'clockmaker','master-room');objectLabel('MASTER CLOCK CHAMBER',[0,15.4,-14.2],.28);for(const [x,y,z,r] of [[-7,3,4,2],[7,6,1,2.4],[-5,10,-8,2.1]])addClockGear('climb gear',[x,y,z],r);makeClockmakerFigure([0,0,12],true);camera.position.set(0,1.7,11);camera.lookAt(-6,2,5);description.textContent='The ascent crosses enormous gears, wide maintenance steps, suspended platforms, and three emergency brakes.';objective.textContent='Pull each brake in order, then enter the Master Clock chamber.';setClockmakerHud();saveClockmaker()}
function buildClockmakerMaster(){clockmaker.phase=6;clockmakerShell('THE MASTER CLOCK',30,30,10);const master=addWorkingClock('master clock',[0,5,-14.7],5.2);clockmakerMasterHands=master;for(const [index,x,z,label] of [[0,-9,-6,'SLOW MINUTE'],[1,-3,-8,'SLOW HOUR'],[2,3,-8,'BRAKE AT 12:00'],[3,9,-6,'PERMANENT LOCK']]){box('master lock '+index,[x,1,z],[2.8,2,1.3],0x59472f,true);interactive([x,1.4,z+1],[3.2,2.7,1.4],8,'clockmaker','master-lock:'+index);objectLabel(clockmaker.masterLocks.includes(index)?`${label} · SET`:`${label} · E`,[x,2.9,z+1],.21)}makeClockmakerFigure([0,0,12],true);camera.position.set(0,1.7,10);camera.lookAt(0,4,-13);description.textContent='The twenty-foot Master Clock spins over four linked mechanisms while darkness and tiny gears move behind the Clockmaker’s broken face.';objective.textContent='Slow both hands, wait for 12:00, engage the brake, then pull the permanent lock.';setClockmakerHud();saveClockmaker()}
function buildClockmakerEscape(){clockmaker.phase=7;clockmakerShell('THE FROZEN TOWER',30,34,10);document.body.classList.add('clockmaker-frozen');for(const [x,z,r] of [[-9,8,2.8],[0,3,3.2],[9,-3,2.7],[-5,-9,2.5]]){const gear=addClockGear('frozen gear platform',[x,.4,z],r);gear.rotation.x=Math.PI/2}for(const [x,z] of [[-8,4],[7,-6]]){const bridge=box('frozen pendulum bridge',[x,.35,z],[1.3,.35,9],0x98733a,false);bridge.rotation.y=x<0?.55:-.55}box('frozen clock hand walkway',[0,.28,-11],[1.1,.35,11],0xb38b45,false).rotation.y=Math.PI/2;box('escape elevator',[0,2,-16.6],[6,4,.3],0x4a5052,false);interactive([0,1.8,-15.7],[5.5,3.6,1.4],8,'clockmaker','escape-elevator');objectLabel('ELEVATOR · GET OUT',[0,4.2,-15.4],.32);makeClockmakerFigure([0,0,7],true);camera.position.set(0,1.7,14);camera.lookAt(0,1.5,-12);description.textContent='Stopped pendulums become bridges, frozen gears become platforms, and clock hands form narrow walkways toward the elevator.';objective.textContent='Cross the frozen tower before the ticking resumes.';setClockmakerHud();saveClockmaker()}
function buildClockmakerAftermath(){clockmakerShell('THE DESCENDING ELEVATOR',12,12,5);clockmaker.complete=true;box('clock tower elevator doors',[0,2,-5.8],[5,4,.3],0x4b5051,false);const display=box('elevator clock display',[0,2.7,-5.5],[2.7,1.2,.16],0x15130f,false);display.material.emissive.setHex(0x7e5c22);display.material.emissiveIntensity=1.6;interactive([0,.5,-1],[2,1.2,2],8,'clockmaker','return-room140');objectLabel('RETURN TO ROOM 140 · E',[0,1.3,-1],.3);camera.position.set(0,1.7,3.5);camera.lookAt(0,2.5,-5);description.textContent='The tower disappears above. The elevator HUD reads 12:00—then advances by one minute.';objective.textContent='The Clockmaker is out of time, but Hotel Nocturne is not.';setClockmakerHud();saveClockmaker()}
function buildClockmakerPhase(){if(clockmaker.complete)return buildClockmakerAftermath();if(clockmaker.phase===1)return buildClockmakerRhythm();if(clockmaker.phase===2)return buildClockmakerFace();if(clockmaker.phase===3)return buildClockmakerFourClocks();if(clockmaker.phase===4)return buildClockmakerBroken();if(clockmaker.phase===5)return buildClockmakerClimb();if(clockmaker.phase===6)return buildClockmakerMaster();return buildClockmakerEscape()}
function startClockmaker(fresh=false){floorOne=null;floorTwo=null;collector=null;drowned=null;pursuer=null;clockmaker=fresh?newClockmakerRun():(loadClockmaker()||newClockmakerRun());clockmaker.dying=false;buildClockmakerPhase();if(fresh){controls.unlock();message('THE CLOCKMAKER',`“You’re late.” The pocket watch closes with a CLICK. Every silent clock begins at once, and the maintenance door locks behind you.`)}}
function clockmakerTimingWindow(){const phase=clockmaker.rhythmTime%4;return phase<.35||phase>3.65}
function advanceClockmaker(phase){clockmaker.phase=phase;clockmaker.rhythmTime=0;clockmaker.lastTick=-1;clockmaker.lastAttack=-1;clockmaker.lastImpact=-1;clockmaker.reverseAnchorZ=null;saveClockmaker();playPurgeCrash();buildClockmakerPhase()}
function handleClockmaker(part){if(!clockmaker||clockmaker.dying)return;if(part.startsWith('lower-lock:')){const index=Number(part.slice(11));if(clockmaker.lowerLocks.includes(index))return;if(!clockmakerTimingWindow())return document.querySelector('#prompt').textContent='MISSED 12 · THE HAND MUST COMPLETE ANOTHER ROTATION';clockmaker.lowerLocks.push(index);pickupTone();saveClockmaker();if(clockmaker.lowerLocks.length===3)return advanceClockmaker(2);objectLabel(`MECHANISM ${index+1} · LOCKED`,[[-10,0,10][index],2.8,-9],.2);setClockmakerHud();return}
 if(part.startsWith('upper-lock:')){const index=Number(part.slice(11));if(clockmaker.upperLocks.includes(index))return;if(!clockmakerTimingWindow())return document.querySelector('#prompt').textContent='THE UPPER HAND PASSED TWELVE · WAIT FOR THE NEXT CYCLE';clockmaker.upperLocks.push(index);pickupTone();saveClockmaker();if(clockmaker.upperLocks.length===2)return advanceClockmaker(3);setClockmakerHud();return}
 if(part.startsWith('clock-hour:')||part.startsWith('clock-minute:')){const hour=part.startsWith('clock-hour:'),index=Number(part.slice(hour?11:13)),state=clockmaker.clocks[index];if(state.locked)return;if(hour)state.hour=state.hour%12+1;else state.minute=(state.minute+15)%60;if(state.hour===12&&state.minute===0){state.locked=true;pickupTone()}const clock=clockmakerClocks[index];if(clock){clock.hourPivot.rotation.z=-state.hour/12*Math.PI*2;clock.minutePivot.rotation.z=-state.minute/60*Math.PI*2}objectLabel(state.locked?`CLOCK ${index+1} · 12:00 LOCKED`:`${String(state.hour).padStart(2,'0')}:${String(state.minute).padStart(2,'0')}`,[[-11,-4,4,11][index],5.8,-15],.2);document.querySelector('#prompt').textContent=state.locked?`CLOCK ${index+1} LOCKED AT MIDNIGHT`:`CLOCK ${index+1} · ${String(state.hour).padStart(2,'0')}:${String(state.minute).padStart(2,'0')}`;saveClockmaker();setClockmakerHud();if(clockmaker.clocks.every(item=>item.locked))return advanceClockmaker(4);return}
 if(part==='climb-start')return advanceClockmaker(5);
 if(part.startsWith('brake:')){const index=Number(part.slice(6));if(clockmaker.brakes.includes(index))return;if(index!==clockmaker.brakes.length)return document.querySelector('#prompt').textContent=`BRAKE ${clockmaker.brakes.length+1} MUST BE PULLED FIRST`;clockmaker.brakes.push(index);pickupTone();playPurgeCrash();saveClockmaker();objective.textContent=clockmaker.brakes.length===3?'The tower is silent. Reach the Master Clock chamber.':`Brake ${index+1} stopped part of the tower. The Clockmaker is moving faster.`;setClockmakerHud();return}
 if(part==='master-room'){if(clockmaker.brakes.length<3)return document.querySelector('#prompt').textContent=`PULL ${3-clockmaker.brakes.length} MORE EMERGENCY BRAKES`;return advanceClockmaker(6)}
 if(part.startsWith('master-lock:')){const index=Number(part.slice(12));if(clockmaker.masterLocks.includes(index))return;if(index!==clockmaker.masterLocks.length)return document.querySelector('#prompt').textContent=`MASTER LOCK ${clockmaker.masterLocks.length+1} MUST BE ENGAGED FIRST`;if(index===2){const aligned=clockmaker.masterHour===12&&clockmaker.masterMinute<1.5||clockmaker.masterHour===11&&clockmaker.masterMinute>=59;if(!aligned)return document.querySelector('#prompt').textContent=`WAIT FOR 12:00 · CURRENT TIME ${clockmakerDisplayTime()}`;clockmaker.masterHour=12;clockmaker.masterMinute=0}clockmaker.masterLocks.push(index);pickupTone();playPurgeCrash();saveClockmaker();if(index===3)return advanceClockmaker(7);setClockmakerHud();return}
 if(part==='escape-elevator')return finishClockmaker();if(part==='return-room140'){clockmaker=null;floorTwo=newFloorTwoRun();floorTwo.phase=19;return buildFloorTwoSafe()}}
function finishClockmaker(){clockmaker.complete=true;clockmaker.endReveal=0;saveClockmaker();saveHotelProgress('clockmaker-out-of-time');buildClockmakerAftermath();controls.unlock();message('THE CLOCKMAKER · OUT OF TIME','The doors close on the restarting tower. The elevator clock reads 12:00. For one silent moment, it seems permanent.')}
function failClockmaker(reason){if(adminPreventDeath(reason))return;if(!clockmaker||clockmaker.dying)return;clockmaker.dying=true;if(clockmaker.phase===2){clockmaker.rhythmTime=0;clockmaker.lastTick=-1;clockmaker.lastAttack=-1;clockmaker.lastImpact=-1;clockmaker.reverseAnchorZ=null}controls.unlock();horrorStinger();const blackout=document.querySelector('#blackout');blackout.querySelector('span').textContent=reason;blackout.classList.add('show');setTimeout(()=>{clockmaker.dying=false;setStability(Math.max(65,stability));buildClockmakerPhase();blackout.classList.remove('show');blackout.querySelector('span').textContent='You wake inside the cabin.'},900)}
function damageClockmaker(amount,reason){if(!clockmaker||clockmaker.damageCooldown>0||adminPreventDeath(reason))return;clockmaker.damageCooldown=1.6;setStability(stability-amount);horrorStinger();document.querySelector('#prompt').textContent=`${reason} · -${amount} COMPOSURE`;if(stability<=0)failClockmaker(reason)}
function clockmakerWatched(){if(!clockmakerEntity)return false;const view=new THREE.Vector3(),toBoss=clockmakerEntity.position.clone().sub(camera.position);camera.getWorldDirection(view);view.y=0;toBoss.y=0;return view.normalize().dot(toBoss.normalize())>.9}
