 const rhythm=clockmaker.rhythmTime%4;document.body.classList.toggle('clockmaker-bell',clockmaker.phase===2&&clockmaker.lastAttack===0&&rhythm>2.65);document.body.classList.toggle('clockmaker-reverse',clockmaker.phase===2&&clockmaker.lastAttack===3);for(const [index,gear] of clockmakerGears.entries()){const reverse=clockmaker.phase===2&&clockmaker.lastAttack===3?-1:1,broken=clockmaker.phase===4?Math.sin(time*(1.2+index*.7))*2.2:1;gear.rotation.z+=dt*reverse*(.35+index*.08)*broken}for(const [index,pendulum] of clockmakerPendulums.entries()){const irregular=clockmaker.phase===4?(Math.sin(time*.73+index)*.45+1):1,angle=Math.sin(time*(1.2+index*.08)*irregular+pendulum.phase)*.78;pendulum.mesh.rotation.z=angle;if(Math.abs(camera.position.z-pendulum.z)<1.2&&Math.abs(camera.position.x-(pendulum.x+Math.sin(angle)*pendulum.range))<1.25)damageClockmaker(clockmaker.phase===4?22:16,'A PENDULUM SWEPT YOU OFF RHYTHM')}
 if(clockmaker.phase===1)return;
