function newPursuerRun(sceneIndex=1,origin='admin'){return{scene:Math.max(1,Math.min(6,sceneIndex)),origin,phase:1,revealTimer:2.8,gates:[],doorProgress:0,stun:0,stumble:0,stepTimer:.35,beltWarning:null,beltReversed:false,complete:false,dying:false,boundary:34,escapeLead:0}}
function savePursuer(){if(pursuer)sessionStorage.setItem('infinite-hotel-pursuer',JSON.stringify(pursuer))}
function loadPursuer(){try{const value=JSON.parse(sessionStorage.getItem('infinite-hotel-pursuer')||'null');return value?{...newPursuerRun(value.scene||1,value.origin||'admin'),...value}:null}catch{return null}}
function savePursuerCompletions(){localStorage.setItem('infinite-hotel-pursuer-scenes-v2',JSON.stringify([...pursuerCompletedScenes].sort()))}
