function buildFloorOnePhase(){
 document.body.classList.remove('floor-one-panic','floor-one-exhausted','floor-one-cough','noise-hunt','chef-lockdown','chef-freezer','chef-blackout','chef-final-service','chef-elevator-finale');if(floorOne.phase===10)document.querySelector('#noise-hud')?.classList.remove('active','danger');else{document.querySelector('#noise-hud')?.classList.add('active');setBossEncounterHud(false)}floorOne.drawerHolding=false;floorOne.drawerProgress=0;floorOne.activeValve=null;floorOne.lookDown=false;floorOne.dying=false;
 if([1,3,5,7,9].includes(floorOne.phase))return buildFloorOneRandomRoom();if(floorOne.phase===2)return buildFloorOneSoundSector();if(floorOne.phase===4)return buildFloorOneElevation();if(floorOne.phase===6)return buildFloorOneLaundry();if(floorOne.phase===8)return buildFloorOneBallroom();if(floorOne.phase===10){if(floorOne.chefStage==='freezer'||floorOne.chefStage==='freezer-dark')return buildFloorOneChefFreezer();if(floorOne.chefStage==='final-service')return buildFloorOneChefFinalService();if(floorOne.chefStage==='elevator-finale'||floorOne.chefStage==='survived')return buildFloorOneChefElevator();return buildFloorOneKitchen()}return finishHotelFloorOne();
}
function buildHotelFloorOneArrival(){hotelRunItems.delete('noise-door-open');hotelRunItems.add('noise-survived');saveHotelRun();floorOne=loadFloorOne()||newFloorOneRun();buildFloorOnePhase();controls.unlock();message('FLOOR 1 · 50 DOORS','The elevator opens at Room 1. Forty-five generated guest rooms and five landmark rooms stand between you and the final lift. Rejoining the hotel reshuffles the generated layouts without erasing your progress.')}
function floorOneAdvance(){
 if(floorOne.phase===5&&floorOne.index===4&&maybeStartPursuer(2,'floor1'))return;const totals={1:9,3:9,5:9,7:9,9:9};if(totals[floorOne.phase]&&floorOne.index+1<totals[floorOne.phase])floorOne.index++;else{if(floorOne.phase===1&&floorOne.gold<5)floorOne.gold=5;floorOne.phase++;floorOne.index=0}saveFloorOne();buildFloorOnePhase();
}
function startFloorOneHunt(source){if(floorOne.huntTimer>0)return;floorOne.noise=100;floorOne.huntTimer=7;floorOneEntity||=makeFloorOneNoiseEntity();floorOneEntity.visible=true;floorOneEntity.position.set(source?.x??camera.position.x,2,(source?.z??camera.position.z)-4);document.body.classList.add('noise-hunt');playNoiseBurst();document.querySelector('#prompt').textContent='THE NOISE TELEPORTED TO THE SOUND · CROUCH AND MOVE'}
function addFloorOneNoise(amount,source){floorOne.noise=THREE.MathUtils.clamp(floorOne.noise+amount,0,100);if(floorOne.noise>=100)startFloorOneHunt(source)}
function floorOneLadderMash(){if(!floorOne?.elevation?.ladderQte)return;floorOne.elevation.ladderPresses++;floorOne.elevation.ladderTimer=1.2;document.querySelector('#prompt').textContent='BROKEN RUNG · MASH E · '+floorOne.elevation.ladderPresses+' / 8';if(floorOne.elevation.ladderPresses>=8){floorOne.phase=5;floorOne.index=0;floorOne.elevation=null;saveFloorOne();buildFloorOnePhase()}}
