 if(part.startsWith('locked:')){floorOne.lockedDrawer=part.slice(7);document.querySelector('#prompt').textContent=usableInventory.lockpicks?'SELECT LOCKPICK AND PRESS Q':'THIS DRAWER NEEDS A LOCKPICK';return}
