function updateFloorOneChefSlam(dt){if(!['escape','final-service'].includes(floorOne.chefStage))return;floorOne.chefSlamCooldown=Math.max(0,floorOne.chefSlamCooldown-dt);const distance=Math.hypot(floorOneChef.position.x-camera.position.x,floorOneChef.position.z-camera.position.z);if(floorOne.chefSlamWindup>0){floorOne.chefSlamWindup-=dt;floorOneChef.rotation.z=Math.sin(performance.now()*.035)*.08;if(floorOne.chefSlamWindup<=0){playPurgeCrash();floorOne.chefSlamCooldown=4.5;floorOneChef.rotation.z=0;if(distance<3&&floorOne.chefDamageCooldown<=0)damageFloorOneChef(20,'THE CUTTING-BOARD SLAM CAUGHT YOU');const debris=box('fallen cutting board',[floorOneChef.position.x,.2,floorOneChef.position.z-1],[2.7,.4,1.3],0x593a25,true);floorOneChefCover.push(debris);setTimeout(()=>{debris.removeFromParent();floorOneChefCover=floorOneChefCover.filter(mesh=>mesh!==debris);solidColliders=solidColliders.filter(collider=>collider.mesh!==debris)},3500);document.querySelector('#prompt').textContent='CLEAVER SLAM · FALLEN KITCHENWARE TEMPORARILY BLOCKS THE ROUTE'}return}if(distance<3.8&&floorOne.chefSlamCooldown<=0&&floorOne.chefDistraction<=0){floorOne.chefSlamWindup=.78;floorOne.chefKnifeMode='cooldown';floorOne.chefKnifeTimer=1.2;document.querySelector('#prompt').textContent='THE CHEF RAISES HIS CLEAVER · GET AWAY FROM THE PREP SURFACE'}}
