 if(part.startsWith('drawer:')){const id=part.slice(7);if(floorTwo.opened.includes(id))return;floorTwo.opened.push(id);document.querySelector('#prompt').textContent=grantDrawerLoot(id,'floor-two');return}
 if(part.startsWith('medicine:')){const id='medicine-'+part.slice(9);if(floorTwo.opened.includes(id))return;floorTwo.opened.push(id);usableInventory.medkits++;saveUsableInventory();saveFloorTwo();pickupTone();return document.querySelector('#prompt').textContent='FIRST-AID KIT ADDED TO INVENTORY'}
