 if(part==='sheet-music'){if(floorTwo.sheetFound)return;floorTwo.sheetFound=true;saveFloorTwo();pickupTone();controls.unlock();return message('BLOOD-INK SHEET MUSIC','The ledger reads: C — E — G — C. Play it on the grand piano.')}
