 if(part.startsWith('ballroom-guest:')){const index=Number(part.slice(15));if(floorTwo.ballroomTagged.includes(index))return;floorTwo.ballroomTagged.push(index);const guest=floorTwoGuests.find(entry=>entry.userData.index===index);if(guest){guest.userData.tagged=true;guest.visible=false}saveFloorTwo();pickupTone();const remaining=6-floorTwo.ballroomTagged.length;if(remaining){objective.textContent=`Keep moving and tag the remaining masked guests. ${remaining} remain.`;return document.querySelector('#prompt').textContent=`GUEST ${index+1} TAGGED · ${remaining} REMAIN`}objective.textContent='All six guests are tagged. Escape through the shattered center window.';document.querySelector('#prompt').textContent='ALL GUESTS TAGGED · THE OUTSIDE SECTOR IS OPEN';playPurgeCrash();return}
 if(part.startsWith('watcher-statue:')){const index=Number(part.slice(15));if(floorTwo.watcherStatues.includes(index))return;floorTwo.watcherStatues.push(index);floorTwo.watcherSolved=floorTwo.watcherStatues.length===3;saveFloorTwo();pickupTone();if(floorTwo.watcherSolved){objective.textContent='All three statues face the gate. Cross the balcony and leave.';return document.querySelector('#prompt').textContent='STATUES ALIGNED · STONE GATE OPEN'}document.querySelector('#prompt').textContent=`STATUE ${index+1} ALIGNED · TURN BACK TO THE WATCHER`;return}
 if(part.startsWith('garden-piece:')){const index=Number(part.slice(13));if(floorTwo.gardenPieces.includes(index))return;floorTwo.gardenPieces.push(index);floorTwo.gardenSolved=floorTwo.gardenPieces.length===3;saveFloorTwo();pickupTone();objective.textContent=floorTwo.gardenSolved?'The emblem is complete. Return to the iron gate.':`Find the remaining gate-emblem pieces. ${3-floorTwo.gardenPieces.length} remain.`;document.querySelector('#prompt').textContent=floorTwo.gardenSolved?'IRON EMBLEM COMPLETE · EXIT OPEN':`GATE PIECE ${index+1} FOUND · ${3-floorTwo.gardenPieces.length} REMAIN`;return}
 if(part.startsWith('window-switch:')){const index=Number(part.slice(14));if(floorTwo.windowSolved)return;if(floorTwo.windowPreview)return document.querySelector('#prompt').textContent='THE PATTERN IS STILL DISPLAYING · WATCH THE WINDOWS';if(index===floorTwo.windowCreatureIndex){floorTwo.windowProgress=0;saveFloorTwo();return resetFloorTwoEncounter('THE WINDOW CREATURE WAS BEHIND THAT SWITCH',()=>{})}const sequence=floorTwo.windowRounds[floorTwo.windowRound];if(index!==sequence[floorTwo.windowProgress]){floorTwo.windowProgress=0;saveFloorTwo();document.querySelector('#prompt').textContent='WRONG WINDOW · THE PATTERN RESTARTS';return buildFloorTwoWindowPuzzle()}floorTwo.windowProgress++;pickupTone();if(floorTwo.windowProgress<sequence.length){saveFloorTwo();return document.querySelector('#prompt').textContent=`CORRECT · ${floorTwo.windowProgress} / ${sequence.length}`}floorTwo.windowRound++;floorTwo.windowProgress=0;if(floorTwo.windowRound>=3){floorTwo.windowSolved=true;saveFloorTwo();playPurgeCrash();objective.textContent='All three patterns are complete. Continue along the façade.';return buildFloorTwoWindowPuzzle()}saveFloorTwo();document.querySelector('#prompt').textContent=`ROUND ${floorTwo.windowRound} COMPLETE · NEXT PATTERN`;return buildFloorTwoWindowPuzzle()}
