function startVentMaze(){controls.unlock();base('ACT I · SECURITY VENTS','SOMETHING IS CRAWLING BEHIND YOU','Choose the correct route through five junctions before it catches you. Wrong turns send you back and cost three seconds.');const route=['LEFT','STRAIGHT','RIGHT','RIGHT','LEFT'],symbols=['← LEFT','↑ STRAIGHT','RIGHT →'];let step=0,timeLeft=20,timer;const display=document.createElement('div'),duct=document.createElement('div'),choices=document.createElement('div');display.className='vent-timer';duct.className='vent-maze';choices.className='choices';const draw=()=>{display.innerHTML=`ESCAPE TIME <strong>${Math.max(0,Math.ceil(timeLeft))}</strong>s · JUNCTION ${step+1}/5<div><span style="width:${Math.max(0,timeLeft/20*100)}%"></span></div>`;duct.innerHTML=`<i class="vent-player" style="left:${8+step*17}%"></i><i class="vent-chaser" style="left:${Math.max(0,8+(20-timeLeft)*3.2)}%"></i>`};function restart(reason){step=0;timeLeft=Math.max(6,timeLeft-3);feedback.textContent=reason;draw()}function finish(){clearInterval(timer);jailbreakItems.add('vent-maze');saveJailbreak();advanceJailbreak('THE VENT MAZE','You kick through a loose grille as claws scrape the metal behind you. The cellblock stretches below.')}symbols.forEach(label=>{const button=document.createElement('button'),direction=label.replace(/[←↑→]/g,'').trim().replace('RIGHT','RIGHT');button.textContent=label;button.onclick=()=>{if(direction===route[step]){step++;feedback.textContent=step<5?'The duct bends. The crawling behind you gets louder.':'You see light through the final grille.';if(step===5)return finish();draw()}else restart('DEAD END — something slams into the duct behind you. Turn back!')};choices.append(button)});timer=setInterval(()=>{if(!dlg.open){clearInterval(timer);return}timeLeft-=.1;if(timeLeft<=0){clearInterval(timer);feedback.textContent='IT CAUGHT YOUR ANKLE — the vent maze resets.';setTimeout(startVentMaze,900);return}draw()},100);body.append(display,duct,choices);draw()}
