function startMazeEscape(){dlg.close();mazeEscape=true;scene.fog.color.setHex(0x4a0903);scene.fog.density=.032;const open=[];for(let y=0;y<MAZE_SIZE;y++)for(let x=0;x<MAZE_SIZE;x++)if(mazeGrid[y][x]===0){const p=mazeWorld(x,y);open.push(p);mazeEscapePlatforms.push({x:p.x,z:p.z,halfX:.82,halfZ:.82,top:.48})}const lava=new THREE.Mesh(new THREE.PlaneGeometry(MAZE_SIZE*MAZE_CELL,MAZE_SIZE*MAZE_CELL),new THREE.MeshStandardMaterial({color:0xff2705,emissive:0xc31302,emissiveIntensity:3.8,roughness:.35}));lava.rotation.x=-Math.PI/2;lava.position.y=.09;lava.name='maze lava';roomGroup.add(lava);const stones=new THREE.InstancedMesh(new THREE.BoxGeometry(1.65,.45,1.65),mat(0x392b22),open.length),matrix=new THREE.Matrix4();open.forEach((p,index)=>{matrix.makeTranslation(p.x,.255,p.z);stones.setMatrixAt(index,matrix)});stones.castShadow=true;stones.receiveShadow=true;roomGroup.add(stones);playerFeetY=.48;verticalVelocity=0;playerGrounded=true;camera.position.y=2.18;const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2);spawnRootChaser(heart);chaseState.headStart=2;mazeChaosHandle=setInterval(()=>{if(mazeEscape)mazeShiftTimer=0},650);document.querySelector('#prompt').textContent='ESCAPE! SPACE TO JUMP · THE FLOOR IS LAVA';setTimeout(()=>controls.lock(),100)}
