function updateEscapeChase(dt){if(!chaseState||!rootChaser||dlg.open)return;if(chaseState.headStart>0){chaseState.headStart-=dt;document.querySelector('#prompt').textContent=`HEAD START: ${Math.max(1,Math.ceil(chaseState.headStart))} · RUN AND JUMP`;if(chaseState.headStart<=0){rootChaser.visible=true;document.querySelector('#prompt').textContent='THE MONSTER IS MOVING · RUN'}return}chaseState.pathTimer-=dt;if(chaseState.pathTimer<=0){chaseState.path=findMazePath(rootChaser.position,camera.position);chaseState.waypoint=1;chaseState.pathTimer=.3}const cell=chaseState.path[chaseState.waypoint];if(cell){const target=mazeWorld(cell[0],cell[1]),direction=target.sub(rootChaser.position);direction.y=0;if(direction.length()<.15)chaseState.waypoint++;else rootChaser.position.add(direction.normalize().multiplyScalar(dt*3.35))}rootChaser.lookAt(camera.position.x,1.5,camera.position.z);const distance=new THREE.Vector2(rootChaser.position.x-camera.position.x,rootChaser.position.z-camera.position.z).length();if(distance<1.1)resetMazeEscape('THE MONSTER CAUGHT YOU')}
