function collectBat(){if(batOwned)return message('BASEBALL BAT','You already have the bat.');batOwned=true;saved[5]=true;localStorage.setItem('cabin-baseball-bat','true');localStorage.setItem('cabin-3d-progress',JSON.stringify(saved));updateHud();controls.unlock();message('BASEBALL BAT COLLECTED','The wood is scarred but solid. Click or press F to swing. Space is used to jump in the Playroom.')}
function startCombat(){if(saved[6])return message('THE EMPTY PLAYROOM','The spider is gone. Its red ball lies split on the floor.');if(!batOwned){controls.unlock();return message('YOU NEED A WEAPON','The spider lifts the ball beneath its fangs. Find something in the Workshop before facing it.')}combat={phase:'waiting',timer:1.1,hits:0,swing:0,velocity:new THREE.Vector3(),elapsed:0};const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.055,.12,2.2,12),mat(0xa8783f));mesh.rotation.z=-1.15;mesh.position.set(.62,-.58,-1.15);camera.add(mesh);batModel=mesh;document.querySelector('#combat-hud').style.display='block';document.querySelector('#creature-hits').textContent='0 / 5';document.querySelector('#prompt').textContent='WASD MOVE · SPACE JUMP · C CROUCH · CLICK/F SWING';controls.lock()}
function swingBat(){if(combat)combat.swing=.28}
function spiderCaughtPlayer(){if(adminPreventDeath('THE SPIDER COULD NOT HURT YOU'))return;if(!combat)return;const blackout=document.querySelector('#blackout');stopCombat();controls.unlock();blackout.querySelector('span').textContent='THE SPIDER CAUGHT YOU';blackout.classList.add('show');setTimeout(()=>{buildRoom(6);blackout.querySelector('span').textContent='You wake inside the cabin.'},900);setTimeout(()=>{blackout.classList.remove('show');document.querySelector('#prompt').textContent='YOU DIED · APPROACH THE SPIDER TO TRY AGAIN';controls.lock()},1900)}
function updateCombat(dt){if(!thrownBall||!creatureModel)return;combat.elapsed+=dt;combat.swing=Math.max(0,combat.swing-dt);creatureModel.userData.legs?.forEach((leg,index)=>{leg.rotation.z=Math.sin(combat.elapsed*9+index*1.7)*.14;leg.rotation.y=Math.sin(combat.elapsed*7+index)*.1;leg.position.y=1.35+Math.sin(combat.elapsed*10+index*Math.PI)*.08});creatureModel.position.y=Math.abs(Math.sin(combat.elapsed*5))*.08;if(batModel)batModel.rotation.z=THREE.MathUtils.lerp(batModel.rotation.z,combat.swing>0?.35:-1.15,Math.min(1,dt*18));if(combat.phase!=='reflected'){const target=new THREE.Vector3(camera.position.x+Math.sin(combat.elapsed*1.9)*2.5,0,camera.position.z+Math.cos(combat.elapsed*1.6)*2.5),direction=target.sub(creatureModel.position);direction.y=0;if(direction.length()>.05)creatureModel.position.add(direction.normalize().multiplyScalar(dt*(1.65+combat.hits*.22)));creatureModel.position.x=THREE.MathUtils.clamp(creatureModel.position.x,-14.5,14.5);creatureModel.position.z=THREE.MathUtils.clamp(creatureModel.position.z,-14.5,14.5);creatureModel.lookAt(camera.position.x,1.5,camera.position.z)}const playerFloor=new THREE.Vector3(camera.position.x,0,camera.position.z),spiderFloor=new THREE.Vector3(creatureModel.position.x,0,creatureModel.position.z);if(playerFloor.distanceTo(spiderFloor)<1.65&&playerFeetY<2.1){spiderCaughtPlayer();return}if(combat.phase==='waiting'){combat.timer-=dt;if(combat.timer<=0){thrownBall.visible=true;thrownBall.position.copy(creatureModel.position).add(new THREE.Vector3(0,1.75,.55));const predicted=camera.position.clone();if(combat.hits>1){const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);predicted.x+=side*(1.1+combat.hits*.2)}combat.velocity.copy(predicted).sub(thrownBall.position).normalize().multiplyScalar(7.2+combat.hits*.85);combat.phase='incoming';document.querySelector('#prompt').textContent='KEEP AWAY FROM THE SPIDER · TOUCHING IT KILLS'}}else if(combat.phase==='incoming'){thrownBall.position.addScaledVector(combat.velocity,dt);const distance=thrownBall.position.distanceTo(camera.position);if(combat.swing>0&&distance<1.55){combat.velocity.copy(creatureModel.position).add(new THREE.Vector3(0,1.7,0)).sub(thrownBall.position).normalize().multiplyScalar(10.5+combat.hits);combat.phase='reflected';document.querySelector('#prompt').textContent='GOOD HIT — KEEP MOVING'}else if(distance<.48){stability=Math.max(0,stability-16);resetThrow('MISSED — DODGE SIDEWAYS OR SWING LATER')}else if(thrownBall.position.length()>35)resetThrow('DODGED — THE SPIDER THROWS AGAIN')}else if(combat.phase==='reflected'){const target=creatureModel.position.clone().add(new THREE.Vector3(0,1.7,0)),desired=target.sub(thrownBall.position).normalize().multiplyScalar(10.5+combat.hits);combat.velocity.lerp(desired,Math.min(1,dt*3));thrownBall.position.addScaledVector(combat.velocity,dt);if(thrownBall.position.distanceTo(creatureModel.position.clone().add(new THREE.Vector3(0,1.7,0)))<.9){combat.hits++;creatureModel.rotation.z+=(combat.hits%2?-.2:.2);document.querySelector('#creature-hits').textContent=`${combat.hits} / 5`;if(combat.hits>=5)winCombat();else resetThrow(`DIRECT HIT ${combat.hits}/5 — THE NEXT THROW IS FASTER`)}}}
function resetThrow(text){thrownBall.visible=false;combat.phase='waiting';combat.timer=Math.max(.55,1.25-combat.hits*.12);document.querySelector('#prompt').textContent=text}
function winCombat(){saved[6]=true;localStorage.setItem('cabin-3d-progress',JSON.stringify(saved));updateHud();stopCombat();controls.unlock();message('THE SPIDER FALLS','The fifth reflected ball strikes between its eyes. Its legs curl beneath its body, revealing the Root Chamber door—but the roots will open only after every puzzle is complete.')}
function stopCombat(){if(batModel){camera.remove(batModel);batModel.geometry.dispose();batModel.material.dispose();batModel=null}if(thrownBall)thrownBall.visible=false;combat=null;document.querySelector('#combat-hud').style.display='none';document.querySelector('#prompt').textContent=room===6?'WASD MOVE · SPACE JUMP · C/CTRL CROUCH · E INTERACT':'WASD TO MOVE · E TO INTERACT'}

const dlg=document.querySelector('#puzzle'),body=document.querySelector('#puzzle-body'),feedback=document.querySelector('#feedback');let gameNoticeTimer=0;function hideGameNotice(){const notice=document.querySelector('#game-notice');clearTimeout(gameNoticeTimer);notice.classList.remove('active');notice.setAttribute('aria-hidden','true')}function showGameNotice(name,copy=''){const notice=document.querySelector('#game-notice');hideGameNotice();notice.querySelector('strong').textContent=name;notice.querySelector('span').textContent=copy;void notice.offsetWidth;notice.classList.add('active');notice.setAttribute('aria-hidden','false');const duration=THREE.MathUtils.clamp(4800+String(copy).length*18,5200,9000);gameNoticeTimer=setTimeout(hideGameNotice,duration)}function scheduleHotelSuitcaseExplosion(){if(!hotelArrivalSuitcasePending)return;hotelArrivalSuitcasePending=false;setTimeout(triggerHotelArrivalExplosion,80)}document.querySelector('.close').onclick=()=>{scheduleHotelSuitcaseExplosion();dlg.close()};dlg.addEventListener('cancel',scheduleHotelSuitcaseExplosion);dlg.addEventListener('close',()=>{scheduleHotelSuitcaseExplosion();dlg.classList.remove('guestbook-ui');controls.lock()});
function openPuzzle(i){controls.unlock();if(i===0)return message('THE INNER DOOR',handlePieces.size===3?'The repaired handle turns. Darkness waits beyond.':`Three broken pieces once formed its handle. You have ${handlePieces.size}.`);if(saved[i])return message('CLUE RECOVERED','This room has given up its secret.');if(i===3){const dates=['1987 · CAMP PERMIT','1996 · NEWSPAPER','2008 · CAMERA','TONIGHT · YOUR BACKPACK'],correct=puzzleRun.trophyReverse?[...dates].reverse():dates;return orderPuzzle('THE MISSING HIKERS',correct,3,`Select the belongings from the ${puzzleRun.trophyReverse?'most recent disappearance to the oldest':'oldest disappearance to the most recent'}.`)}if(i===4)return cellarPuzzle();if(i===7)return orderPuzzle('THE LAST BINDING',puzzleRun.mazeBinding,7,'Follow the current runes carved around the heart. Solving them begins the final escape.');const data=i===1?['THE MIRROR’S WARNING',puzzleRun.warning]:['THE CABIN OWNER’S RITUAL',puzzleRun.ritual];orderPuzzle(data[0],data[1],i)}
function base(kicker,name,copy='Choose the pieces in their true order.'){hideGameNotice();if(floorTwo&&hotelSideScene.startsWith('floor-two'))kicker=kicker.replace(/ROOM \d+/,`ROOM ${floorTwoCurrentRoomNumber()}`);document.querySelector('#puzzle-kicker').textContent=kicker;document.querySelector('#puzzle-title').textContent=name;document.querySelector('#puzzle-copy').textContent=copy;body.innerHTML='';feedback.textContent='';if(!dlg.open)dlg.showModal()}
function message(name,copy){if(dlg.open)dlg.close();showGameNotice(name,copy);if(!inLobby&&storySelect.hidden&&!intro.open)armGameplayControls();return true}
function cellarPuzzle(){
 base('CHAPTER V','THE PRESSURE PUMP',`Open and close the three valves. Their pressures combine. Reach exactly ${puzzleRun.cellarTarget} PSI, then drain the cellar.`);
 let pressure=0;const active=new Set(),readout=document.createElement('div'),valves=document.createElement('div');
 readout.className='handle-count';readout.textContent='0 PSI';valves.className='choices';
 [[3,'RED VALVE · 3 PSI'],[5,'GREEN VALVE · 5 PSI'],[8,'BRASS VALVE · 8 PSI']].forEach(([value,label])=>{
  const button=document.createElement('button');button.textContent=label;
  button.onclick=()=>{if(active.has(value)){active.delete(value);pressure-=value;button.classList.remove('used')}else{active.add(value);pressure+=value;button.classList.add('used')}readout.textContent=`${pressure} PSI`;feedback.textContent=pressure>puzzleRun.cellarTarget?'The pipes shake violently. Pressure is too high.':pressure===puzzleRun.cellarTarget?'The gauge needle rests inside the narrow green band.':'Water continues rising around the hatch.'};
  valves.append(button);
 });
 const drain=document.createElement('button');drain.textContent='ENGAGE DRAIN PUMP';
 drain.onclick=()=>{if(pressure===puzzleRun.cellarTarget){feedback.textContent='The pump roars. Black water spirals away from the hatch.';setTimeout(()=>solve(4),650)}else feedback.textContent=`The safety lock refuses at ${pressure} PSI. The diagram marks exactly ${puzzleRun.cellarTarget}.`};
 body.append(readout,valves,drain);
}
function solve(i){if(i===7){startMazeEscape();chaseState.headStart=5;return}saved[i]=true;localStorage.setItem('cabin-3d-progress',JSON.stringify(saved));updateHud();message(`CHAPTER ${['I','II','III','IV','V','VI','VII','VIII'][i]} COMPLETE`,'The cabin groans. Somewhere, another door unlocks.')}
function orderPuzzle(name,correct,i,instructions='Choose the pieces in their true order.'){
 base(rooms[i][0],name,instructions);let chosen=[];const wrap=document.createElement('div');wrap.className='choices';
 [...correct].sort(()=>Math.random()-.5).forEach(word=>{
  const b=document.createElement('button');b.textContent=word;
  b.onclick=()=>{b.classList.add('used');chosen.push(word);feedback.textContent=chosen.join(' → ');if(chosen.length===4){if(chosen.join()==correct.join())setTimeout(()=>solve(i),500);else{feedback.textContent='That answer does not match this playthrough’s clue.';setTimeout(()=>orderPuzzle(name,correct,i,instructions),1100)}}};
  wrap.append(b);
 });
 body.append(wrap);
}
function cipherPuzzle(){base('MEMORY IV','THE UNSENT LETTER','Shift UHPHPEHU backward three letters.');const input=document.createElement('input');input.placeholder='_ _ _ _ _ _ _ _';const b=document.createElement('button');b.textContent='UNSEAL THE LETTER';b.onclick=()=>input.value.trim().toUpperCase()==='REMEMBER'?solve(3):feedback.textContent='Move every letter three places backward.';body.append(input,b)}
function nurseryPuzzle(){base('MEMORY I','THE MUSIC BOX','Turn clockwise and match the changing heartbeat for six seconds.');body.innerHTML='<div class="crank-grid"><div class="dial"><span class="arm"></span></div><div class="readout"><div class="heart">♥</div><strong id="bpm">72 BPM</strong><strong id="rpm">0 RPM</strong></div></div><div class="progress"><span></span></div>';const dial=body.querySelector('.dial'),arm=body.querySelector('.arm'),heart=body.querySelector('.heart'),fill=body.querySelector('.progress span');let target=72,rpm=0,match=0,drag=false,lastA=0,lastT=performance.now(),started=false,beats=0;const ac=new AudioContext();function beat(){if(!dlg.open||saved[0])return;heart.classList.add('beat');setTimeout(()=>heart.classList.remove('beat'),120);const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=55;g.gain.setValueAtTime(.15,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.14);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.15);if(++beats%4===0){target=[62,72,84,96,76][Math.floor(Math.random()*5)];body.querySelector('#bpm').textContent=`${target} BPM`}setTimeout(beat,60000/target)}beat();function angle(e){const r=dial.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2)}dial.onpointerdown=e=>{drag=true;lastA=angle(e);lastT=performance.now();dial.setPointerCapture(e.pointerId)};dial.onpointermove=e=>{if(!drag)return;const a=angle(e),now=performance.now();let d=a-lastA;if(d>Math.PI)d-=Math.PI*2;if(d<-Math.PI)d+=Math.PI*2;if(d>0){rpm=rpm*.65+Math.min(150,d/(Math.PI*2)*60000/(now-lastT))*.35;started=true}arm.style.transform=`rotate(${a+Math.PI/2}rad)`;lastA=a;lastT=now};dial.onpointerup=()=>drag=false;const tick=setInterval(()=>{if(!dlg.open){clearInterval(tick);return}rpm*=.91;body.querySelector('#rpm').textContent=`${Math.round(rpm)} RPM`;const diff=rpm-target;if(started&&Math.abs(diff)<=13){match+=.1;feedback.textContent='The rhythms are aligning…'}else if(started&&diff>13){match=Math.max(0,match-.18);feedback.textContent='Too fast—the dolls are moving.';dolls.forEach(d=>d.position.lerp(camera.position,.035))}else if(started){match=Math.max(0,match-.12);stability=Math.max(0,stability-.3);feedback.textContent='Too slow—your memory is fading.'}fill.style.width=`${Math.min(100,match/6*100)}%`;document.querySelector('#stability-fill').style.width=`${stability}%`;document.querySelector('#stability-text').textContent=`MEMORY STABILITY ${Math.round(stability)}%`;if(stability<=0){stability=55;dlg.close();message('MEMORY FRACTURED','You wake beside the music box again.')}if(match>=6){clearInterval(tick);solve(0)}},100)}
document.querySelector('#hint').onclick=()=>{controls.unlock();const hotelSequence=currentHotelSequence(),hints=[handlePieces.size===0?'Search low beside the table. Brass catches the light.':handlePieces.size===1?'One piece was placed higher than the others.':handlePieces.size===2?'The last piece lies near where you woke.':'The inner door is ready.',`This run’s mirror warning begins with “${puzzleRun.warning[0]}” and ends with “${puzzleRun.warning.at(-1)}.”`,`This run’s ritual begins with ${puzzleRun.ritual[0]} and ends with ${puzzleRun.ritual.at(-1)}.`,puzzleRun.trophyReverse?'Begin with your backpack from tonight and work backward to 1987.':'Begin with the 1987 permit and work forward to tonight.',`Combine the 3, 5, and 8 PSI valves to make exactly ${puzzleRun.cellarTarget}.`,'Take the baseball bat from the workbench.','Keep moving. Space jumps, C crouches, and click or F swings. Hit the spider five times.',`This run’s heart binding begins with “${puzzleRun.mazeBinding[0]}.”`,hotelStage===0?'The lobby is waiting for four responses: ring the bell, take the key, inspect the elevator, and read the guestbook.':hotelStage===1?`The painting’s sequence begins at ${hotelSequence.start} and increases by ${hotelSequence.step}. Examine the object that does not belong and remember its mark. Complete all five patterns.`:'The hotel changes its rules in every impossible room.'];message('THE CABIN WHISPERS',hints[room])};
document.querySelector('#story-lobby').onclick=()=>{activeStory='lobby';inJailbreak=false;controls.unlock();buildStoryLobby()};
document.querySelector('#hint').addEventListener('click',event=>{if(activeStory!=='jailbreak')return;event.stopImmediatePropagation();const hints=['Search the bunk and sink. The vent screws read II, IV, I, III.','Read the guard schedule before touching the keypad.','Blood, sky, grass, warning describe the breaker colors.','The sheet from your cell can be tied to the yard drain pipe.','Search the maintenance locker for something that can cut the floodgate chain.','The 3 and 8 PSI valves total the marked pressure of 11.','Wire the truck in diagram order, then use its power on the shutter.','Hold Shift, weave around the barricades, jump when needed, and reach the green lights before the guard catches you.','You are free. Return to the Story Lobby to choose another branch.'];controls.unlock();message('A PRISONER’S WHISPER',hints[jailbreakStage])},true);
document.querySelector('#reset-game').onclick=()=>{controls.unlock();if(confirm('Reset the game and generate a new set of puzzles? All saved progress will be erased.')){localStorage.removeItem('cabin-3d-progress');localStorage.removeItem('cabin-handle-pieces');localStorage.removeItem('cabin-baseball-bat');localStorage.removeItem('cabin-bonus-puzzles');localStorage.removeItem('cabin-secret-chain');localStorage.removeItem('infinite-hotel-progress');localStorage.removeItem('infinite-hotel-stage');localStorage.removeItem('infinite-hotel-reality');localStorage.removeItem('infinite-hotel-arrival-items');localStorage.removeItem('infinite-hotel-pursuer-scenes-v2');localStorage.removeItem('hotel-player-name');localStorage.removeItem('escape-usable-inventory');localStorage.removeItem('escape-admin-items');localStorage.removeItem('jailbreak-stage');localStorage.removeItem('jailbreak-items');localStorage.removeItem('courage-shards');localStorage.removeItem('cabin-puzzle-run');sessionStorage.removeItem('cabin-puzzle-run');sessionStorage.removeItem('infinite-hotel-run-floor');sessionStorage.removeItem('infinite-hotel-run-room');sessionStorage.removeItem('infinite-hotel-run-items');sessionStorage.removeItem('infinite-hotel-bosses');sessionStorage.removeItem('infinite-hotel-noise-arc-room');sessionStorage.removeItem('infinite-hotel-floor-five');sessionStorage.removeItem('infinite-hotel-floor-one');sessionStorage.removeItem('infinite-hotel-floor-two');sessionStorage.removeItem('infinite-hotel-pursuer');location.reload()}};
const resetHotelSideSceneBeforePassages=resetHotelSideScene;resetHotelSideScene=function(){hotelRoomPassage=null;return resetHotelSideSceneBeforePassages()};
